        views.push({ file: 'Views/Home/Index.cshtml', lang: 'text', code: "@model List<TaskItem>\n@{ Layout = null; }\n<!doctype html>\n<html lang=\"en\">\n<meta charset=\"utf-8\">\n<title>Tasks</title>\n<script src=\"https://unpkg.com/htmx.org@@2.0.11\"></script>\n<body hx-headers='{\"RequestVerificationToken\": \"@Html.AntiForgeryRequestToken()\"}'>\n<h1>Tasks</h1>\n" + (login ? "<form method=\"post\" action=\"/logout\"><button>Log out</button></form>\n" : '') + (a.payment ? "<form method=\"post\" action=\"/api/checkout\"><button>Buy example product</button></form>\n" : '') + "<form hx-post=\"/Home/Add\" hx-target=\"#list\" hx-on::after-request=\"this.reset()\">\n  <input name=\"title\" maxlength=\"200\" required>\n  <button>Add</button>\n</form>\n<div id=\"list\" hx-get=\"/Home/List\" hx-trigger=\"reload\"><partial name=\"_List\" model=\"Model\" /></div>\n" + liveScript + "</body>\n</html>\n", lines: [['@model', 'The data this page receives.'], ['Layout = null', 'This page has no shared layout file.'], ['htmx', 'A small library that lets HTML attributes make requests and update part of the page.'], ['@@', 'Razor treats <code>@</code> as code, so a literal one is written twice.'], ['hx-headers', 'Sends the anti-forgery token with every htmx request.'], ['hx-post', 'Submits the form to this URL without reloading the page.'], ['hx-target', 'Replaces this element with the response.'], ['partial', 'Inserts another view.']] });
