      t += "\n    [Fact]\n    public async Task RestApiAddsChangesAndListsTasks()\n    {\n        var client = factory.CreateClient();\n        var created = await client.PostAsJsonAsync(\"/api/tasks\", new { title = \"Through the API\" });\n        Assert.Equal(HttpStatusCode.Created, created.StatusCode);\n        var task = (await created.Content.ReadFromJsonAsync<TaskItem>())!;\n        var changed = await client.PutAsJsonAsync(\"/api/tasks/\" + task.Id, new { done = true });\n        Assert.True((await changed.Content.ReadFromJsonAsync<TaskItem>())!.Done);\n        var list = await client.GetAsync(\"/api/tasks\");\n        Assert.True(list.Content.Headers.Contains(\"Content-Range\"));\n        var tasks = (await list.Content.ReadFromJsonAsync<List<TaskItem>>())!;\n        Assert.Contains(tasks, x => x.Id == task.Id);\n    }\n\n    [Fact]\n    public async Task EmptyTitleIsRejected()\n    {\n        var response = await factory.CreateClient().PostAsJsonAsync(\"/api/tasks\", new { title = \" \" });\n        Assert.Equal(HttpStatusCode.BadRequest, response.StatusCode);\n    }\n";
